    public static double runUntil(SimState state, Func<SimState, bool> done, double max = 2000)
    {
        for (var t = 0; t < max; t++)
        {
            if (Js.T(done(state)))
            {
                return t;
            }
            Tick.tick(state);
            expect(Invariants.checkInvariants(state), DebugText.dumpText(state)).toEqual(Js.Arr([]));
        }
        throw new Exception($"condition not met after {Js.Str(max)} ticks\n{Js.Str(DebugText.dumpText(state))}");
    }

    /// <summary>tools</summary>
    public class D001_tools
    {

        [Fact(DisplayName = "tools > a builder picks up a hammer, and builds faster with it")]
        public void T002_a_builder_picks_up_a_hammer_and_builds_faster_with_it()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 3, map = ["s..S"] });
            var s = Js.NN(Js.Get(state.survivors, 0));
            s.priorities = new(JobTypes.NO_JOBS) { ["build"] = 2 };
            runUntil(state, (_) => s.tool != null, 200);
            double sum(string type)
            {
                double n = 0;
                for (var t = 0; t < 30; t++)
                {
                    state.tick = Js.I(1000 + t);
                    n += Skills.workStep(state, s, type);
                }
                return n;
            }
            expect(sum("build")).toBeGreaterThan(sum("farm"));
        }
    }

    /// <summary>the auto-wall planner</summary>
    public class D003_the_auto_wall_planner
    {

        [Fact(DisplayName = "the auto-wall planner > plans edge walls round the box with a door in each side")]
        public void T004_plans_edge_walls_round_the_box_with_a_door_in_each_side()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 3, map = [".......", ".......", ".......", ".......", "......."] });
            expect(Commands.applyCommand(state, new Command { type = "planPerimeter", x0 = Js.I(1), y0 = Js.I(1), x1 = Js.I(5), y1 = Js.I(3) }).ok).toBe(true);
            expect(state.blueprints.every((b) => b.side != null)).toBe(true);
            expect(state.blueprints.filter((b) => b.target == "wall")).toHaveLength(16 - 4);
            expect(state.blueprints.filter((b) => b.target == "door").map((b) => Js.Arr([b.x, b.y, b.side]))).toEqual(Js.Arr([Js.Arr([3, 1, "n"]), Js.Arr([3, 4, "n"]), Js.Arr([1, 2, "w"]), Js.Arr([6, 2, "w"])]));
        }
    }

    /// <summary>the radio</summary>
    public class D005_the_radio
    {

        [Fact(DisplayName = "the radio > a powered radio hears a call; requests can be met for goodwill")]
        public void T006_a_powered_radio_hears_a_call_requests_can_be_met_for_goodwil()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 3, map = ["s.I.E", "fffff"] });
            Js.NN(state.furniture.find((f) => f.kind == "generator")).stored = 2;
            state.settlements.push(new() { id = "n1", name = "Testville", x = Js.I(0), y = Js.I(0), reputation = 0, people = 8, food = 32, defence = 1, ties = new() {  }, unfolded = true, lastTalk = -1, lastRaid = -1 });
            double day = 1;
            while (((state.requests.length == 0) && !state.pointsOfInterest.some((p) => p.label == Radio.DISTRESS_LABEL)) && (day < 40))
            {
                state.tick = Js.I((day * Time.DAY_LENGTH) + ((Radio.RADIO_HOUR - 6) * Time.TICKS_PER_HOUR));
                Radio.updateRadio(state);
                day += 1;
            }
            expect(day).toBeLessThan(40);
            state.requests = [new() { id = "r1", settlementId = "n1", kind = "food", count = 5, until = state.tick + Time.DAY_LENGTH }];
            expect(Radio.fulfilRequest(state, "r1")).toBeNull();
            expect(Js.NN(Js.Get(state.settlements, 0)).reputation).toBe(Radio.REQUEST_REP);
            expect(Hash.hashRoll(1)).toBeLessThan(1);
        }
    }
